[
  {
    "id": "c001",
    "name": "Release and party definitions",
    "text": "KNOW ALL MEN BY THESE PRESENTS, thst in considerstion of THREE HUNDRED AND FIFTY THOUSAND end 00/100 DOLLARS ($350,000.00) paid to ENTAIRE GLOBAL COMPANIES, INC., ENTAIRE GLOBAL FINANCIAL, INC., JONATHAN D. ROSEN AND WILLIAM R. MUIRHEAD (hereinafter referred to as “Releasors”) hereby release and forever discharge AMERICAN GUARANTEE AND LIABILITY INSURANCE COMPANY, together with its past or present officer, directors cmmployees, agents, attorneys, insurers, affiliated companies, subcontractors, subsidiaries, parestt | companies, successors and assigns, jointly and severally, (hereinafter collectively referred to as “Releasees”) from any and all consequences of the incident(s) underlying or giving rise to the following lawsuits: Civil Action No. 2006-cv-120104 in the Superior Court of Fulton County, and Civil Action No. 07-CV-6694-9 in the Superior Court of DeKalb County (hereinafter collectively “the Lawsuits”), and any and all consequences arising from the Lawsuits themselves (Releasors and Releasees to be collectively referred to as the “Parties’)."
  },
  {
    "id": "c002",
    "name": "Release intent and consideration",
    "text": "Releasors have previously presented Releases with a claim for damages arising out of the Lawsuits and it is the intent of Releasors to release Releasees from any and all claims, damages, loss, whether known or unknown, made or which could have been made, which are directly or indirectly related to the Lawsuits in exchange for the payment set forth above."
  },
  {
    "id": "c003",
    "name": "Covenant not to sue",
    "text": "Additionally, Releasors covenant not to sue Releasees for any claim, damage, or loss whether known or unknown, which are directly or imdirectly related to the Lawsuits or the incidents underlying or giving rise to the Lawsuits."
  },
  {
    "id": "c004",
    "name": "Reciprocal release",
    "text": "Likewise, Releasees release Releasors from any and all claims, damages, loss, whether known or unknown, made or which could have been made, which are directly or indirectly related to the Lawsuits, as part of the consideration for Releasors’"
  },
  {
    "id": "c005",
    "name": "No assignment or subrogation representation",
    "text": "Releasors further represent and warrant that they have not assigned to any othec person or party all or any portion of the claim whatsoever that ENTAIRE GLOBAL COMPANIES, INC,, ENTAIRE GLOBAL FINANCIAL, INC., JONATHAN D. ROSEN AND WILLIAM R. MUIRHEAD may have or claim to have against Releasees, and that no other person or party is subrogated to any of Releasors’ rights in this matter."
  },
  {
    "id": "c006",
    "name": "Paragraph 4 — Entire agreement",
    "text": "4, ‘That no promise or inducement or agreement not herein expressed has been made by the Parties and that this Release contains the entire agreement between the Parties, and that the terms of this reement ae conzartunl an not 8 mere rsa"
  },
  {
    "id": "c007",
    "name": "5. No assignment or subrogation representation",
    "text": "5. Releasors further represent and werrent that Releasors have not assigned to any other person or party all or any portion of the claim whatsoever that Releasors may have or claim to have against Releases and that no other person or party is subrogated to any of Releasors’ rights in this matter."
  },
  {
    "id": "c008",
    "name": "Reliance on Releasors’ representations",
    "text": "Reteasors onderstund and acknowledge that Releases, in providing the consideration herein described, duly rely upon the truth, aocuracy and validity of all promises, representations and warranties of the Releasors contained herein."
  },
  {
    "id": "c009",
    "name": "No liability and compromise",
    "text": "If IS FURTHER UNDERSTOOD AND AGREED that Parties admnit no liability to each other, or others, and that this settlement is » compromise of doubtful end disputed claims, and that the considerations exchanged herein shall not be construed as an admission of liability on the part of Releasees or Releasors, but that said liability is disputed and specifically denied by Releasees and Releasors."
  },
  {
    "id": "c010",
    "name": "Release of all actions and claims",
    "text": "IT IS UNDERSTOOD AND AGREED that this is a Release of any and all actions, causes of actions, rights of action, claims and demands of whatsoever kind and nature between ‘the Parties arising from and for, upon or by reason of any damage, loss or injury, known or unknown, which may be traced either directly or indirectly to the Lawsuits or any incident or occurrence underlying or giving rise to the Lawsuits, even to the extent of death, or as may appear at any time in the future, no matter how remotely any such potential claim may be related fo the Lawsuits or any incident or occurrence underlying or giving rise to the Lawsuits."
  },
  {
    "id": "c011",
    "name": "Indemnification against claims and liens",
    "text": "IT IS FURTHER UNDERSTOOD AND AGREED that Releasors do hereby agree to protect, indemnify and hold harmless Releases against any claim or lien, or any other subrogation claim or lien by any insurance company, government agency, law firm, inclading, but not limited to, Alston & Bird LLP and Mason Bahr LLP, or any other entity related to the Lawsuits or any incident or oocurrence underlying or giving rise to the Lawsuits."
  },
  {
    "id": "c012",
    "name": "Full and final satisfaction",
    "text": "The consideration referenced herein is accepted in compromise and settlement, and is Full and Final Satisfaction of any and all claiths, whether specifically stated or not, which were asserted or might have been asserted by the Parties in the Lawsuits."
  },
  {
    "id": "c013",
    "name": "Unnumbered — Confidentiality and no-detriment",
    "text": "IT IS FURTHER UNDERSTOOD AND AGREED thatthe fms ofthis Reeve ani Se terms of the settlement of this claim shall not be used to the detriment of the Parties, shall remain confidential, and shall not be daclosed 10 aay person not party or privy to this settement except as may be required by law."
  },
  {
    "id": "c014",
    "name": "Acknowledgment of terms and legal counsel",
    "text": "In entering into this Release, Parties represent that they have read all the terms hereof and understand and voluntarily accept all the terms hereof, and that they have been adequately represented and advised by their own legal counsel."
  },
  {
    "id": "c015",
    "name": "Governing law",
    "text": "This Release shall be construed and interpreted in accordance with the laws of the State ofGeorgia,"
  }
]

